// Demo for the C++ RL-DAgger-GRU policy.
//
//   g++ -std=c++17 -O2 -Icpp cpp/rl_dagger_gru_demo.cpp -o rl_dagger_gru_demo
//   ./rl_dagger_gru_demo
//
// Weights header generated by:
//   python3 -m ipd export --arch gru \
//     --weights weights/rl_dagger_gru_weights.json \
//     --out cpp/rl_dagger_gru_weights.hpp
//   sed -i 's/namespace gru_policy_weights/namespace rl_dagger_gru_weights/g' \
//     cpp/rl_dagger_gru_weights.hpp
#include <cstdio>
#include <vector>

#include "opponents/demo.hpp"
#include "policies/rl_dagger_gru_policy.hpp"

int main() {
    ipd::RLDAggerGRUParams params;
    params.sample = false;
    ipd::RLDAggerGRUPolicy policy(20261024u, params);
    std::printf("features=%zu hidden=%d layers=%d\n",
                policy.features({}, {}).size(),
                rl_dagger_gru_weights::HIDDEN,
                rl_dagger_gru_weights::NUM_LAYERS);
    for (const auto& opponent : ipd::demo_opponents()) {
        std::printf("%-10s %4d\n", opponent.name.c_str(),
                    ipd::play_against(policy, opponent));
    }
    return 0;
}
